} from "@/components/ui/select";
import { formatProtoformMessage } from "../../../lib/core/messages";
import { useAutoForm } from "../context";
import type { AutoFormFieldProps } from "../core-types";
import {
  type DataProviderOption,
  type DataProviderRequest,
  getStaleSelections,
  type ResolvedDataProvider,
  resolveDataProvider,
  useDataProviderSignal,
} from "../data-providers";
import { getPathInObject } from "../field-utils";
import type { FieldTypeDefinition } from "../registry";
import { safeStringify } from "../utils/serialization";
import {
  getControlLabel,
  getFlatOptions,
  getGroupedOptions,
  hasNumericOptions,
  readDataProviderId,
  renderOptionLabel,
  useFieldTestIds,
} from "./shared";

function SelectFieldComponent({ error, field, id, inputProps, label, path }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const { dataProviders, formatMessage, formValues } = useAutoForm();
  const providerId = readDataProviderId(field);
  const provider = resolveDataProvider(dataProviders, providerId);
  const dependencyValues = Object.fromEntries(
    (provider?.dependencies ?? []).map((dependency) => [dependency, getPathInObject(formValues, dependency.split("."))])
  );
  const numericOptions = hasNumericOptions(field);
  const currentValue =
    inputProps["value"] === undefined || inputProps["value"] === null ? null : String(inputProps["value"]);
  const fieldLabel = getControlLabel(label, field);
  const optionGroups = getGroupedOptions(field);
  const flatOptions = getFlatOptions(field);

  if (provider) {
    return (
      <SelectFieldFromProvider
        currentValue={currentValue}
        dependencyValues={dependencyValues}
        error={error}
        field={field}
        id={id}
        inputProps={inputProps}
        key={safeStringify(dependencyValues)}
        path={path}
        provider={provider}
        testIds={testIds}
      />
    );
  }

  return (
    <Select
      items={[
        ...(field.required
          ? []
          : [
              {
                label: formatProtoformMessage(formatMessage, "auto_form.select.not_set", {}, "Not set"),
                value: null,
              },
            ]),
        ...flatOptions.map((option) => ({
          label: renderOptionLabel(option),
          value: option.value,
        })),
      ]}
      onValueChange={(value) => {
        if (value === null) {
          inputProps["onValueChange"](undefined);
          return;
        }
        inputProps["onValueChange"](numericOptions ? Number(value) : value);
      }}
      value={currentValue}
    >
      <SelectTrigger
        aria-label={fieldLabel}
        className={error ? "border-destructive" : ""}
        disabled={inputProps["disabled"]}
        id={id}
        testId={testIds.control}
      >
        <SelectValue
          placeholder={formatProtoformMessage(formatMessage, "auto_form.select.placeholder", {}, "Select an option")}
        />
      </SelectTrigger>
      <SelectContent>
        {field.required ? null : (
          <SelectItem testId={testIds.option("not-set")} value={null}>
            {formatProtoformMessage(formatMessage, "auto_form.select.not_set", {}, "Not set")}
          </SelectItem>
        )}
        {optionGroups && optionGroups.length > 0
          ? optionGroups.map((group) => (
              <SelectGroup
                key={`${field.key}-group-${String(group.label ?? group.options.map((option) => option.value).join("-"))}`}
                testId={testIds.group(String(group.label ?? group.options.map((option) => option.value).join("-")))}
              >
                {group.label ? <SelectLabel>{group.label}</SelectLabel> : null}
                {group.options.map((option) => (
                  <SelectItem key={option.value} testId={testIds.option(option.value)} value={option.value}>
                    {renderOptionLabel(option)}
                  </SelectItem>
                ))}
              </SelectGroup>
            ))
          : flatOptions.map((option) => (
              <SelectItem key={option.value} testId={testIds.option(option.value)} value={option.value}>
                {renderOptionLabel(option)}
              </SelectItem>
            ))}
      </SelectContent>
    </Select>
  );
}

function SelectFieldFromProvider({
  currentValue,
  dependencyValues,
  error,
  field,
  id,
  inputProps,
  path,
  provider,
  testIds,
}: {
  currentValue: string | null;
  dependencyValues: DataProviderRequest["dependencyValues"];
  error: AutoFormFieldProps["error"];
  field: AutoFormFieldProps["field"];
  id: string;
  inputProps: AutoFormFieldProps["inputProps"];
  path: string[];
  provider: ResolvedDataProvider;
  testIds: ReturnType<typeof useFieldTestIds>;
}) {
  "use no memo";

  const { formatMessage } = useAutoForm();
  const [query, setQuery] = React.useState("");
  const [cursor, setCursor] = React.useState<string>();
  const [loadedOptions, setLoadedOptions] = React.useState<DataProviderOption[]>([]);
  const fieldPath = path.join(".");
  const selectedValues = currentValue === null ? [] : [currentValue];
  const requestKey = safeStringify({ cursor, dependencyValues, fieldPath, query, selectedValues });
  const signal = useDataProviderSignal(requestKey);
  const {
    options,
    isLoading,
    error: providerError,
    nextCursor,
  } = provider.useProvider({
    cursor,
    dependencyValues,
    fieldPath,
    query,
    selectedValues,
    signal,
  });
  const optionsKey = safeStringify(
    options.map(({ description, group, label, value }) => ({ description, group, label, value }))
  );
  const providerPageKey = requestKey.concat(":", optionsKey);
  const collectedPageKey = React.useRef<string | undefined>(undefined);
  const availableOptions =
    isLoading || providerError ? loadedOptions : mergeProviderOptions(cursor ? loadedOptions : [], options);
  const staleSelections = isLoading || providerError ? [] : getStaleSelections(availableOptions, selectedValues);
  const renderedOptions: DataProviderOption[] =
    provider.staleSelection === "clear"
      ? availableOptions
      : [...staleSelections.map((value) => ({ label: value, value })), ...availableOptions];

  React.useEffect(
    function collectProviderPageEffect() {
      if (isLoading || providerError || collectedPageKey.current === providerPageKey) {
        return;
      }
      collectedPageKey.current = providerPageKey;
      setLoadedOptions((currentOptions) => mergeProviderOptions(cursor ? currentOptions : [], options));
    },
    [cursor, isLoading, options, providerError, providerPageKey]
  );

  const applyUnavailableSelectionClear = React.useEffectEvent(() => inputProps["onValueChange"](undefined));
  const staleSelectionKey =
    provider.staleSelection === "clear" && staleSelections.length > 0 ? (currentValue ?? "") : undefined;

  React.useEffect(
    function clearUnavailableSelection() {
      if (staleSelectionKey !== undefined) {
        applyUnavailableSelectionClear();
      }
    },
    [staleSelectionKey]
  );

  if (providerError) {
    return (
      <Combobox
        disabled
        id={id}
        onChange={() => undefined}
        options={[]}
        placeholder={formatProtoformMessage(formatMessage, "auto_form.select.load_error", {}, "Failed to load options")}
        testId={testIds.control}
      />
    );
  }

  const comboboxOptions: ComboboxOption[] = renderedOptions.map((option) => ({
    data: option,
    group: option.group,
    label: option.label,
    testId: testIds.option(option.value),
    value: option.value,
  }));

  return (
    <div className="space-y-2">
      <Combobox
        className={error ? "[&_input]:border-destructive" : undefined}
        clearable={!field.required}
        disabled={Boolean(inputProps["disabled"])}
        emptyState={formatProtoformMessage(formatMessage, "auto_form.select.empty", {}, "No options found.")}
        id={id}
        loading={isLoading}
        onChange={(value) => {
          if (value === "") {
            inputProps["onValueChange"](undefined);
            return;
          }
          inputProps["onValueChange"](field.type === "number" ? Number(value) : value);
        }}
        onInputValueChange={(value) => {
          setQuery(value);
          setCursor(undefined);
        }}
        options={comboboxOptions}
        placeholder={formatProtoformMessage(
          formatMessage,
          isLoading ? "auto_form.select.loading" : "auto_form.select.placeholder",
          {},
          isLoading ? "Loading…" : "Select an option"
        )}
        renderOption={(option) => {
          const { data } = option;
          return isDataProviderOption(data) ? <ProviderOptionLabel option={data} /> : option.label;
        }}
        testId={testIds.control}
        value={currentValue ?? ""}
      />
      {provider.staleSelection === "error" && staleSelections.length > 0 ? (
        <p className="text-destructive text-sm" role="alert">
          {formatProtoformMessage(
            formatMessage,
            "auto_form.select.stale",
            { value: staleSelections.join(", ") },
            "Selected value is no longer available."
          )}
        </p>
      ) : null}
      {nextCursor ? (
        <Button onClick={() => setCursor(nextCursor)} type="button" variant="outline">
          {formatProtoformMessage(formatMessage, "auto_form.load_more", {}, "Load more")}
        </Button>
      ) : null}
    </div>
  );
}

function isDataProviderOption(value: unknown): value is DataProviderOption {
  return Boolean(
    value &&
      typeof value === "object" &&
      typeof Reflect.get(value, "label") === "string" &&
      typeof Reflect.get(value, "value") === "string"
  );
}

function mergeProviderOptions(
  currentOptions: DataProviderOption[],
  pageOptions: readonly DataProviderOption[]
): DataProviderOption[] {
  const merged = new Map(currentOptions.map((option) => [option.value, option]));
  for (const option of pageOptions) {
    merged.set(option.value, option);
  }
  const nextOptions = [...merged.values()];
  if (
    nextOptions.length === currentOptions.length &&
    nextOptions.every((option, index) => {
      const current = currentOptions[index];
      if (!current) {
        return false;
      }
      return (
        current.description === option.description &&
        current.group === option.group &&
        current.icon === option.icon &&
        current.label === option.label &&
        current.value === option.value
      );
    })
  ) {
    return currentOptions;
  }
  return nextOptions;
}

function ProviderOptionLabel({ option }: { option: DataProviderOption }) {
  const labelWithIcon = option.icon ? (
    <span className="flex items-center gap-2">
      <span className="flex size-4 shrink-0 items-center justify-center [&>svg]:size-full">{option.icon}</span>
      <span>{option.label}</span>
    </span>
  ) : (
    <span>{option.label}</span>
  );

  if (!option.description) {
    return labelWithIcon;
  }
  return (
    <span className="flex items-center justify-between gap-3">
      {labelWithIcon}
      <span className="text-muted-foreground text-xs">{option.description}</span>
    </span>
  );
}

export { SelectFieldComponent };

export const selectFieldDefinition: FieldTypeDefinition = {
  component: SelectFieldComponent,
  match: (field) => {
    if (field.type !== "select") {
      return false;
    }
    const optionCount = field.options?.length ?? 0;
    return optionCount > 3 && optionCount <= 8;
  },
  name: "select",
  priority: 12,
};

/**
 * Second routing rule for the same `SelectFieldComponent`. Matches any
 * field annotated with `data_provider`, regardless of its underlying
 * proto type — a string field with `data_provider = AWS_REGIONS`
 * becomes a select populated from the hosting app's data-provider
 * registry. High priority so the annotation wins over the default
 * `string` / `password` / `email` matchers.
 *
 * The same component handles both rules; the routing split exists only
 * because static proto-enum selects and annotation-driven selects
 * match under different conditions.
 */
export const dataProviderSelectFieldDefinition: FieldTypeDefinition = {
  component: SelectFieldComponent,
  match: (field) => {
    // Arrays / maps / objects keep their native renderers even when the
    // parent field is annotated with a data provider. Support for
    // array-of-strings multi-select from a data provider is a follow-up.
    if (field.type !== "string" && field.type !== "number") {
      return false;
    }
    return readDataProviderId(field) !== undefined;
  },
  name: "dataProviderSelect",
  priority: 120,
};

"use client";

import { format, isValid, parse } from "date-fns";
import React from "react";

import { Input } from "@/components/ui/input";
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from "@/components/ui/input-group";
import { useAutoFormRuntimeContext } from "../context";
import type { AutoFormFieldProps } from "../core-types";
import { getFieldUiConfig, NUMERIC_OPTION_PATTERN } from "../helpers";
import { getAutoFormChoiceTestId, getAutoFormFieldTestId } from "../test-ids";
import type { AutoFormOptionGroup, AutoFormOptionItem } from "../types";

const TIME_ZONE_SUFFIX_PATTERN = /([+-]\d{2}:\d{2}|Z)$/u;

// ---------------------------------------------------------------------------
// Label utilities
// ---------------------------------------------------------------------------

export function getControlLabel(label: AutoFormFieldProps["label"], field: AutoFormFieldProps["field"]): string {
  return typeof label === "string" || typeof label === "number"
    ? String(label)
    : String(field.fieldConfig?.label ?? field.key);
}

// ---------------------------------------------------------------------------
// Test-id utilities
// ---------------------------------------------------------------------------

export function useFieldTestIds(id: string) {
  const { testIdPrefix } = useAutoFormRuntimeContext();

  return React.useMemo(
    () => ({
      control: getAutoFormFieldTestId(testIdPrefix, id, "control"),
      controlPart: (part: string) => getAutoFormFieldTestId(testIdPrefix, id, `control-${part}`),
      field: getAutoFormFieldTestId(testIdPrefix, id),
      group: (group: string | number) => getAutoFormChoiceTestId(testIdPrefix, id, "group", group),
      option: (value: string | number) => getAutoFormChoiceTestId(testIdPrefix, id, "option", value),
      selected: (value: string | number) => getAutoFormChoiceTestId(testIdPrefix, id, "selected", value),
    }),
    [id, testIdPrefix]
  );
}

export function resolveControlTestId(inputProps: AutoFormFieldProps["inputProps"], fallback: string): string {
  return typeof inputProps.testId === "string" ? inputProps.testId : fallback;
}

// ---------------------------------------------------------------------------
// Date utilities
// ---------------------------------------------------------------------------

export function normalizeDateValue(value: unknown): string {
  if (typeof value === "string") {
    if (TIME_ZONE_SUFFIX_PATTERN.test(value)) {
      const parsed = new Date(value);
      return Number.isNaN(parsed.getTime()) ? "" : format(parsed, "yyyy-MM-dd");
    }

    return value.includes("T") ? (value.split("T")[0] ?? "") : value;
  }

  if (value instanceof Date && isValid(value)) {
    return format(value, "yyyy-MM-dd");
  }

  return "";
}

export function normalizeTimeValue(value: unknown): string {
  if (typeof value === "string") {
    if (TIME_ZONE_SUFFIX_PATTERN.test(value)) {
      const parsed = new Date(value);
      return Number.isNaN(parsed.getTime()) ? "" : format(parsed, "HH:mm");
    }

    return value.includes("T") ? (value.split("T")[1]?.slice(0, 5) ?? "") : "";
  }

  if (value instanceof Date && isValid(value)) {
    return format(value, "HH:mm");
  }

  return "";
}

export function parseCalendarDate(value: string): Date | undefined {
  if (!value) {
    return;
  }

  const parsed = parse(value, "yyyy-MM-dd", new Date());
  return isValid(parsed) ? parsed : undefined;
}

export function buildTimestampValue(datePart: string, timePart: string): string {
  if (!datePart) {
    return "";
  }

  return `${datePart}T${timePart || "00:00"}`;
}

// ---------------------------------------------------------------------------
// Number utilities
// ---------------------------------------------------------------------------

export function parseNumericProp(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  return;
}

export function resolveNumericStep(inputProps: AutoFormFieldProps["inputProps"], fallbackValue?: number): number {
  const explicitStep = parseNumericProp(inputProps["step"]);
  if (explicitStep !== undefined && explicitStep > 0) {
    return explicitStep;
  }

  const values = [parseNumericProp(inputProps["min"]), parseNumericProp(inputProps["max"]), fallbackValue].filter(
    (value): value is number => value !== undefined
  );
  return values.some((value) => !Number.isInteger(value)) ? 0.01 : 1;
}

export function normalizeNumberValue(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  return;
}

// ---------------------------------------------------------------------------
// Option utilities
// ---------------------------------------------------------------------------

export function getGroupedOptions(field: AutoFormFieldProps["field"]): AutoFormOptionGroup[] | undefined {
  return getFieldUiConfig(field).optionGroups;
}

export function getFlatOptions(field: AutoFormFieldProps["field"]): AutoFormOptionItem[] {
  const uiConfig = getFieldUiConfig(field);
  const labelOverrides = uiConfig.optionLabels;
  const optionGroups = getGroupedOptions(field);

  if (optionGroups && optionGroups.length > 0) {
    const options = optionGroups.flatMap((group) => group.options);
    if (labelOverrides) {
      return options.map((opt) => ({ ...opt, label: labelOverrides[opt.value] ?? opt.label }));
    }
    return options;
  }

  return (field.options || []).map(([value, label]) => ({
    label: labelOverrides?.[value] ?? label,
    value,
  }));
}

export function renderOptionLabel(option: AutoFormOptionItem | { label?: React.ReactNode; value: string }) {
  return (
    <span className="flex min-w-0 items-center gap-2">
      {"icon" in option && option.icon ? <span className="shrink-0">{option.icon}</span> : null}
      <span className="truncate">{option.label ?? option.value}</span>
    </span>
  );
}

export function hasNumericOptions(field: AutoFormFieldProps["field"]): boolean {
  const options = getFlatOptions(field);
  return options.length > 0 && options.every((option) => NUMERIC_OPTION_PATTERN.test(option.value));
}

// ---------------------------------------------------------------------------
// Shared input component
// ---------------------------------------------------------------------------

export function StringLikeInput({
  error,
  icon,
  id,
  inputProps,
  placeholder,
  testId,
  type = "text",
}: {
  error?: string | undefined;
  icon?: React.ReactNode | undefined;
  id: string;
  inputProps: AutoFormFieldProps["inputProps"];
  placeholder?: string | undefined;
  testId: string;
  type?: React.ComponentProps<typeof Input>["type"];
}) {
  "use no memo";

  if (icon) {
    return (
      <InputGroup testId={testId}>
        <InputGroupAddon>
          <InputGroupText>{icon}</InputGroupText>
        </InputGroupAddon>
        <InputGroupInput
          aria-invalid={Boolean(error)}
          disabled={inputProps.disabled}
          id={id}
          name={inputProps.name}
          onBlur={inputProps.onBlur}
          onChange={(event) => inputProps.onValueChange(event.target.value)}
          placeholder={placeholder}
          ref={inputProps.ref}
          testId={`${testId}-input`}
          type={type}
          value={typeof inputProps.value === "string" ? inputProps.value : ""}
        />
      </InputGroup>
    );
  }

  return (
    <Input
      aria-invalid={Boolean(error)}
      className={error ? "border-destructive" : ""}
      disabled={inputProps.disabled}
      id={id}
      name={inputProps.name}
      onBlur={inputProps.onBlur}
      onChange={(event) => inputProps.onValueChange(event.target.value)}
      placeholder={placeholder}
      ref={inputProps.ref}
      testId={testId}
      type={type}
      value={typeof inputProps.value === "string" ? inputProps.value : ""}
    />
  );
}

/**
 * Extract the registered data-provider id from a field's customData.
 * Accepts both the flat `customData.dataProvider` shape and the proto-derived
 * `customData.ui.dataProvider` shape so authors can use either.
 */
export function readDataProviderId(field: AutoFormFieldProps["field"] | undefined): string | undefined {
  const customData = field?.fieldConfig?.customData;
  if (!(customData && typeof customData === "object")) {
    return;
  }
  const bag = customData as { dataProvider?: unknown; ui?: { dataProvider?: unknown } };
  if (typeof bag.dataProvider === "string") {
    return bag.dataProvider;
  }
  if (bag.ui && typeof bag.ui === "object" && typeof bag.ui.dataProvider === "string") {
    return bag.ui.dataProvider;
  }
  return;
}

"use client";

import React from "react";
import { Input } from "@/components/ui/input";
import { Slider } from "@/components/ui/slider";
import type { AutoFormFieldProps } from "../core-types";
import { getFieldUiConfig } from "../helpers";
import type { FieldTypeDefinition } from "../registry";
import { normalizeNumberValue, parseNumericProp, resolveNumericStep, useFieldTestIds } from "./shared";

/**
 * Slider widget — renders the track alongside a companion numeric
 * input. The track is for quick coarse adjustments; the input
 * handles precise entry (including tiny step sizes beyond a drag's
 * resolution) and keeps the value readable when the track is tiny
 * on narrow columns. Both controls bind to the same form value.
 */
function SliderFieldComponent({ error, field, id, inputProps, label: fieldLabel }: AutoFormFieldProps) {
  const testIds = useFieldTestIds(id);
  const min = parseNumericProp(inputProps["min"]) ?? 0;
  const max = parseNumericProp(inputProps["max"]) ?? 100;
  const value = normalizeNumberValue(inputProps["value"]) ?? min;
  const step = resolveNumericStep(inputProps, value);
  const clamped = Math.min(max, Math.max(min, value));
  const label = typeof fieldLabel === "string" || typeof fieldLabel === "number" ? String(fieldLabel) : id;

  // Seed the form state with the slider's minimum on mount when the
  // field is undefined/null. Without this, the track renders at `min`
  // (thanks to the `?? min` fallback above) but the companion number
  // input shows as empty and the form value stays undefined — users
  // see a "blank" input even though the slider is clearly at zero.
  // Seeding once aligns both controls visually and makes 0 (or the
  // proto-declared min) an explicit starting value in the payload.
  const hasSeededRef = React.useRef(false);
  React.useEffect(() => {
    if (hasSeededRef.current) {
      return;
    }
    if (inputProps["value"] === undefined || inputProps["value"] === null) {
      hasSeededRef.current = true;
      inputProps["onValueChange"](min, {
        shouldDirty: false,
        shouldTouch: false,
        shouldValidate: false,
      });
    }
  }, [inputProps, min]);
  const inputValue = inputProps["value"];
  const displayValue = typeof inputValue === "number" || typeof inputValue === "string" ? inputValue : clamped;

  return (
    <div className="flex items-center gap-4" data-testid={testIds.control}>
      <Slider
        aria-label={`${label} slider`}
        className="flex-1"
        disabled={inputProps["disabled"]}
        max={max}
        min={min}
        onValueChange={(nextValues) => inputProps["onValueChange"](nextValues[0] ?? min)}
        step={step}
        testId={testIds.controlPart("slider")}
        value={[clamped]}
      />
      <Input
        aria-invalid={Boolean(error)}
        className={`w-24 ${error ? "border-destructive" : ""}`}
        disabled={inputProps["disabled"]}
        id={id}
        inputMode="decimal"
        max={max}
        min={min}
        onBlur={inputProps["onBlur"]}
        onChange={(event) => {
          const nextValue = event.target.value;
          inputProps["onValueChange"](nextValue === "" ? min : Number(nextValue));
        }}
        placeholder={getFieldUiConfig(field).placeholder}
        step={step}
        testId={testIds.controlPart("input")}
        type="number"
        value={displayValue}
      />
    </div>
  );
}

export { SliderFieldComponent };

export const sliderFieldDefinition: FieldTypeDefinition = {
  component: SliderFieldComponent,
  /**
   * Slider is an opt-in widget — it renders only when the proto field
   * carries `field_ui.control = CONTROL_TYPE_SLIDER` (surfaced as
   * `customData.ui.control === 'slider'`). A numeric field with
   * `min`/`max` alone does NOT auto-promote to slider, because that
   * collides with the plain number renderer and produces the
   * "slider + standalone number input" double-render seen on
   * Max In Flight fields before this change. Proto drives the choice.
   */
  match: (field) => {
    if (field.type !== "number") {
      return false;
    }
    const customData = field.fieldConfig?.customData;
    if (!(customData && typeof customData === "object")) {
      return false;
    }
    const bag = customData as { control?: unknown; ui?: { control?: unknown } };
    if (bag.control === "slider") {
      return true;
    }
    if (bag.ui && typeof bag.ui === "object" && bag.ui.control === "slider") {
      return true;
    }
    return false;
  },
  name: "slider",
  priority: 15,
};

