import { TrashIcon } from "lucide-react";
import React from "react";
import { Button } from "@/components/ui/button";
import { formatProtoformMessage } from "../../../lib/core/messages";
import { useAutoFormRenderContext, useAutoFormRuntimeContext } from "../context";
import type { ParsedField } from "../core-types";
import { type AutoFormArrayController, useAutoFormEngine } from "../engine";
import { formSpacing } from "../form-spacing";
import { createEmptyFieldValue, getFieldErrorMessage } from "../helpers";
import { FormDepthProvider, useFormDepth } from "../layout-context";
import { getAutoFormCollectionRemoveTestId, getAutoFormCollectionRowTestId, getAutoFormFieldTestId } from "../test-ids";
import { AutoFormFieldRenderer } from ".";
import { cloneFieldForCompactRow, getRenderedLabel, isComplexCollectionField, useFieldPresentation } from "./shared";

const COMPACT_ROW_GRID = "grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3";

function RequiredArraySeeder({
  controller,
  disabled,
  field,
  itemField,
}: {
  controller: AutoFormArrayController;
  disabled: boolean;
  field: ParsedField;
  itemField: ParsedField | undefined;
}) {
  const hasSeededRef = React.useRef(false);
  React.useEffect(() => {
    if (hasSeededRef.current || disabled || !field.required || controller.items.length > 0 || !itemField) {
      return;
    }
    hasSeededRef.current = true;
    controller.append(createEmptyFieldValue(itemField));
  }, [controller, disabled, field.required, itemField]);
  return null;
}

function getCollectionItemLabel(collectionLabel: string, index: number): string {
  let singularLabel = collectionLabel;
  if (collectionLabel.endsWith("ies")) {
    singularLabel = `${collectionLabel.slice(0, -3)}y`;
  } else if (collectionLabel.endsWith("s")) {
    singularLabel = collectionLabel.slice(0, -1);
  }

  return `${singularLabel} ${index + 1}`;
}

export function ArrayFieldRenderer({
  field,
  path,
  inheritedDisabled = false,
}: {
  field: ParsedField;
  path: string[];
  inheritedDisabled?: boolean;
}) {
  const { uiComponents } = useAutoFormRenderContext();
  const { ArrayController, errors } = useAutoFormEngine();
  const { formatMessage, testIdPrefix } = useAutoFormRuntimeContext();
  const fullPath = path.join(".");
  const itemField = field.schema?.[0];
  const error = getFieldErrorMessage(errors, path);
  const label = getRenderedLabel(field);
  const { isDisabled, isVisible, renderField } = useFieldPresentation(field, path, inheritedDisabled);
  const FieldWrapperComponent = field.fieldConfig?.fieldWrapper ?? uiComponents.FieldWrapper;
  const ArrayWrapperComponent = uiComponents.ArrayWrapper as React.ComponentType<
    React.ComponentProps<typeof uiComponents.ArrayWrapper> & {
      addButtonLabel?: string;
      addButtonTestId?: string;
      testId?: string;
    }
  >;
  const ArrayElementWrapperComponent = uiComponents.ArrayElementWrapper as React.ComponentType<
    React.ComponentProps<typeof uiComponents.ArrayElementWrapper> & {
      removeButtonAriaLabel?: string;
      removeButtonTestId?: string;
      testId?: string;
    }
  >;
  const compactItemField = itemField ? cloneFieldForCompactRow(itemField) : undefined;
  const useCompactRows = itemField ? !isComplexCollectionField(itemField) : false;
  const depth = useFormDepth();
  const addItemLabel = formatProtoformMessage(formatMessage, "auto_form.add_item", { label }, `Add ${label}`);
  const removeItemLabel = formatProtoformMessage(formatMessage, "auto_form.remove_item", {}, "Remove item");

  if (!isVisible) {
    return null;
  }

  return (
    <FieldWrapperComponent error={error} field={renderField} id={fullPath} label={label}>
      <ArrayController name={fullPath}>
        {(controller) => (
          <>
            <RequiredArraySeeder controller={controller} disabled={isDisabled} field={field} itemField={itemField} />
            <ArrayWrapperComponent
              addButtonLabel={addItemLabel}
              addButtonTestId={getAutoFormFieldTestId(testIdPrefix, fullPath, "add")}
              field={renderField}
              label={label}
              onAddItem={() => {
                if (!isDisabled) {
                  controller.append(createEmptyFieldValue(itemField));
                }
              }}
              testId={getAutoFormFieldTestId(testIdPrefix, fullPath, "items")}
            >
              {controller.items.map((item, index) => {
                const rowTestId = getAutoFormCollectionRowTestId(testIdPrefix, fullPath, index);
                const removeButtonTestId = getAutoFormCollectionRemoveTestId(testIdPrefix, fullPath, index);
                const removeItem = () => {
                  if (!isDisabled) {
                    controller.remove(index);
                  }
                };

                if (compactItemField && useCompactRows) {
                  return (
                    <div
                      className={index > 0 ? `${COMPACT_ROW_GRID} ${formSpacing.arrayItemSeparator}` : COMPACT_ROW_GRID}
                      data-testid={rowTestId}
                      key={item.key}
                    >
                      <AutoFormFieldRenderer
                        field={compactItemField}
                        inheritedDisabled={isDisabled}
                        path={[...path, String(index)]}
                      />
                      <Button
                        aria-label={removeItemLabel}
                        disabled={isDisabled}
                        onClick={removeItem}
                        size="icon-sm"
                        testId={removeButtonTestId}
                        type="button"
                        variant="ghost"
                      >
                        <TrashIcon className="size-4" />
                      </Button>
                    </div>
                  );
                }

                const renderedItemField = itemField
                  ? {
                      ...itemField,
                      fieldConfig: {
                        ...(itemField.fieldConfig ?? {}),
                        label: getCollectionItemLabel(label, index),
                      },
                    }
                  : undefined;

                return (
                  <ArrayElementWrapperComponent
                    index={index}
                    key={item.key}
                    onRemove={removeItem}
                    removeButtonAriaLabel={removeItemLabel}
                    removeButtonTestId={removeButtonTestId}
                    testId={rowTestId}
                  >
                    {renderedItemField ? (
                      <FormDepthProvider depth={depth + 1}>
                        <AutoFormFieldRenderer
                          field={renderedItemField}
                          inheritedDisabled={isDisabled}
                          path={[...path, String(index)]}
                        />
                      </FormDepthProvider>
                    ) : null}
                  </ArrayElementWrapperComponent>
                );
              })}
            </ArrayWrapperComponent>
          </>
        )}
      </ArrayController>
    </FieldWrapperComponent>
  );
}

"use client";

import type React from "react";
import { useAutoFormRenderContext, useAutoFormRuntimeContext } from "../context";
import type { AutoFormFieldProps, ParsedField } from "../core-types";
import { useAutoFormEngine } from "../engine";
import { getAutoFormFieldTestId } from "../test-ids";
import { getRenderedLabel, useFieldPresentation } from "./shared";

export function ControlledFieldRenderer({
  field,
  path,
  renderType,
  inheritedDisabled = false,
}: {
  field: ParsedField;
  path: string[];
  renderType?: string;
  inheritedDisabled?: boolean;
}) {
  const { formComponents, uiComponents } = useAutoFormRenderContext();
  const { FieldController } = useAutoFormEngine();
  const fullPath = path.join(".");
  const label = getRenderedLabel(field);
  const {
    isVisible,
    renderField,
    renderType: inferredRenderType,
  } = useFieldPresentation(field, path, inheritedDisabled);
  const { fieldRegistry, testIdPrefix } = useAutoFormRuntimeContext();

  if (!isVisible) {
    return null;
  }

  const resolvedRenderType = renderType ?? inferredRenderType;
  const FieldWrapperComponent = field.fieldConfig?.fieldWrapper ?? uiComponents.FieldWrapper;
  const registeredComponent =
    formComponents[resolvedRenderType] ??
    fieldRegistry?.list().find((definition) => definition.name === resolvedRenderType)?.component;
  const FieldComponent = (registeredComponent ?? formComponents.fallback) as React.ComponentType<AutoFormFieldProps>;
  const componentField = registeredComponent
    ? renderField
    : {
        ...renderField,
        type: resolvedRenderType,
      };

  return (
    <FieldController name={fullPath}>
      {(controller) => {
        const error = controller.errors.join("\n") || undefined;
        return (
          <FieldWrapperComponent error={error} field={renderField} id={fullPath} label={label}>
            <FieldComponent
              error={error}
              field={componentField}
              id={fullPath}
              inputProps={{
                ...renderField.fieldConfig?.inputProps,
                name: controller.name,
                onBlur: controller.onBlur,
                onChange: controller.onChange,
                onCheckedChange: controller.onChange,
                onValueChange: controller.onChange,
                ref: controller.ref,
                required: renderField.required,
                testId: getAutoFormFieldTestId(testIdPrefix, path, "control"),
                value: controller.value,
              }}
              label={label}
              path={path}
              value={controller.value}
            />
          </FieldWrapperComponent>
        );
      }}
    </FieldController>
  );
}

"use client";

import React from "react";
import { useAutoForm } from "../context";
import type { ParsedField } from "../core-types";
import { defaultRegistry } from "../fields";
import { getFieldUiConfig, resolveRenderFieldType } from "../helpers";
import { buildFieldMatchContext, type FieldTypeRegistry } from "../registry";
import type { AutoFormSlotProps } from "../slot";
import { ArrayFieldRenderer } from "./array";
import { ControlledFieldRenderer } from "./controlled";
import { MapFieldRenderer } from "./map";
import { ObjectFieldRenderer } from "./object";
import { OneofFieldRenderer } from "./oneof";
import { isFieldHidden } from "./shared";

function resolveFieldType(field: ParsedField, registry: FieldTypeRegistry<string>): string {
  const explicitControl = getFieldUiConfig(field).control;
  if (explicitControl) {
    return explicitControl;
  }

  const matchContext = buildFieldMatchContext(field);
  const resolved = registry.resolve(field, matchContext);
  return resolved?.name ?? resolveRenderFieldType(field);
}

export function AutoFormFieldRenderer({
  field,
  path,
  inheritedDisabled = false,
  registry,
}: {
  field: ParsedField;
  path: string[];
  inheritedDisabled?: boolean | undefined;
  registry?: FieldTypeRegistry<string> | undefined;
}) {
  const activeRegistry = registry ?? defaultRegistry;
  const renderType = resolveFieldType(field, activeRegistry);

  if ((field.type === "array" || field.type === "map" || field.type === "object") && renderType !== field.type) {
    return (
      <ControlledFieldRenderer
        field={field}
        inheritedDisabled={inheritedDisabled}
        path={path}
        renderType={renderType}
      />
    );
  }

  switch (field.type) {
    case "object":
      return <ObjectFieldRenderer field={field} inheritedDisabled={inheritedDisabled} path={path} />;
    case "array":
      return <ArrayFieldRenderer field={field} inheritedDisabled={inheritedDisabled} path={path} />;
    case "map":
      return <MapFieldRenderer field={field} inheritedDisabled={inheritedDisabled} path={path} />;
    case "oneof":
      return <OneofFieldRenderer field={field} inheritedDisabled={inheritedDisabled} path={path} />;
    default:
      return (
        <ControlledFieldRenderer
          field={field}
          inheritedDisabled={inheritedDisabled}
          path={path}
          renderType={renderType}
        />
      );
  }
}

interface SlotEntry {
  after?: string | undefined;
  before?: string | undefined;
  content: React.ReactNode;
}

function extractSlots(children: React.ReactNode): { slots: SlotEntry[]; other: React.ReactNode[] } {
  const slots: SlotEntry[] = [];
  const other: React.ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child) && (child.type as { displayName?: string }).displayName === "AutoFormSlot") {
      const props = child.props as AutoFormSlotProps;
      slots.push({
        after: props.after,
        before: props.before,
        content: props.children,
      });
    } else if (child !== null && child !== undefined) {
      other.push(child);
    }
  });

  return { other, slots };
}

export function AutoFormFields({ fields, children }: { fields: ParsedField[]; children?: React.ReactNode }) {
  const { deprecatedFields, fieldRegistry } = useAutoForm();
  const { slots, other } = React.useMemo(() => extractSlots(children), [children]);

  // Build slot maps for O(1) lookup
  const beforeSlots = React.useMemo(() => {
    const map = new Map<string, React.ReactNode[]>();
    for (const slot of slots) {
      if (slot.before) {
        const existing = map.get(slot.before) ?? [];
        existing.push(slot.content);
        map.set(slot.before, existing);
      }
    }
    return map;
  }, [slots]);

  const afterSlots = React.useMemo(() => {
    const map = new Map<string, React.ReactNode[]>();
    for (const slot of slots) {
      if (slot.after) {
        const existing = map.get(slot.after) ?? [];
        existing.push(slot.content);
        map.set(slot.after, existing);
      }
    }
    return map;
  }, [slots]);

  // Slots without before/after render at the top
  const topSlots: React.ReactNode[] = [];
  for (const slot of slots) {
    if (!(slot.before || slot.after)) {
      topSlots.push(slot.content);
    }
  }
  const visibleFields = fields.filter((field) => !isFieldHidden(field, deprecatedFields));

  return (
    <div className="divide-y divide-border/60" data-slot="auto-form-fields">
      {topSlots.map((content, i) => (
        <div className="py-7 first:pt-0 last:pb-0" key={`slot-top-${i}`}>
          {content}
        </div>
      ))}
      {other.length > 0
        ? other.map((content, i) => (
            <div className="py-7 first:pt-0 last:pb-0" key={`other-${i}`}>
              {content}
            </div>
          ))
        : null}
      {visibleFields.map((field) => (
        <div className="py-7 first:pt-0 last:pb-0" data-slot="auto-form-field-row" key={field.key}>
          {beforeSlots.get(field.key)?.map((content, i) => (
            <React.Fragment key={`before-${field.key}-${i}`}>{content}</React.Fragment>
          ))}
          <AutoFormFieldRenderer field={field} path={[field.key]} registry={fieldRegistry} />
          {afterSlots.get(field.key)?.map((content, i) => (
            <React.Fragment key={`after-${field.key}-${i}`}>{content}</React.Fragment>
          ))}
        </div>
      ))}
    </div>
  );
}

