import { TrashIcon } from "lucide-react";
import type React from "react";
import { Button } from "@/components/ui/button";
import { formatProtoformMessage } from "../../../lib/core/messages";
import { useAutoFormRenderContext, useAutoFormRuntimeContext } from "../context";
import type { ParsedField } from "../core-types";
import { useAutoFormEngine } from "../engine";
import { formSpacing } from "../form-spacing";
import { createEmptyFieldValue, getFieldErrorMessage } from "../helpers";
import { getAutoFormCollectionRemoveTestId, getAutoFormCollectionRowTestId, getAutoFormFieldTestId } from "../test-ids";
import { AutoFormFieldRenderer } from ".";
import { cloneFieldForCompactRow, getRenderedLabel, isComplexCollectionField, useFieldPresentation } from "./shared";

const COMPACT_PAIR_GRID = "grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto] items-center gap-3";
const KEY_REMOVE_GRID = "grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3";

export function MapFieldRenderer({
  field,
  path,
  inheritedDisabled = false,
}: {
  field: ParsedField;
  path: string[];
  inheritedDisabled?: boolean;
}) {
  const { uiComponents } = useAutoFormRenderContext();
  const { ArrayController, errors } = useAutoFormEngine();
  const { formatMessage, testIdPrefix } = useAutoFormRuntimeContext();
  const fullPath = path.join(".");
  const keyField = field.schema?.[0];
  const valueField = field.schema?.[1];
  const error = getFieldErrorMessage(errors, path);
  const label = getRenderedLabel(field);
  const { isDisabled, isVisible, renderField } = useFieldPresentation(field, path, inheritedDisabled);
  const FieldWrapperComponent = field.fieldConfig?.fieldWrapper ?? uiComponents.FieldWrapper;
  const ArrayWrapperComponent = uiComponents.ArrayWrapper as React.ComponentType<
    React.ComponentProps<typeof uiComponents.ArrayWrapper> & {
      addButtonTestId?: string;
      testId?: string;
    }
  >;
  const compactKeyField = keyField ? cloneFieldForCompactRow(keyField) : undefined;
  const compactValueField = valueField ? cloneFieldForCompactRow(valueField) : undefined;
  const valueIsComplex = isComplexCollectionField(valueField);
  const removeItemLabel = formatProtoformMessage(formatMessage, "auto_form.remove_item", {}, "Remove item");

  if (!isVisible) {
    return null;
  }

  return (
    <FieldWrapperComponent error={error} field={renderField} id={fullPath} label={label}>
      <ArrayController name={fullPath}>
        {(controller) => (
          <ArrayWrapperComponent
            addButtonTestId={getAutoFormFieldTestId(testIdPrefix, fullPath, "add")}
            field={renderField}
            label={label}
            onAddItem={() => {
              if (!isDisabled) {
                controller.append({ key: "", value: createEmptyFieldValue(valueField) });
              }
            }}
            testId={getAutoFormFieldTestId(testIdPrefix, fullPath, "items")}
          >
            {controller.items.map((item, index) => {
              const rowTestId = getAutoFormCollectionRowTestId(testIdPrefix, fullPath, index);
              const removeButtonTestId = getAutoFormCollectionRemoveTestId(testIdPrefix, fullPath, index);
              const removeEntry = () => {
                if (!isDisabled) {
                  controller.remove(index);
                }
              };

              if (compactKeyField && compactValueField && !valueIsComplex) {
                return (
                  <div
                    className={index > 0 ? `${COMPACT_PAIR_GRID} ${formSpacing.arrayItemSeparator}` : COMPACT_PAIR_GRID}
                    data-testid={rowTestId}
                    key={item.key}
                  >
                    <AutoFormFieldRenderer
                      field={compactKeyField}
                      inheritedDisabled={isDisabled}
                      path={[...path, String(index), "key"]}
                    />
                    <AutoFormFieldRenderer
                      field={compactValueField}
                      inheritedDisabled={isDisabled}
                      path={[...path, String(index), "value"]}
                    />
                    <Button
                      aria-label={removeItemLabel}
                      disabled={isDisabled}
                      onClick={removeEntry}
                      size="icon-sm"
                      testId={removeButtonTestId}
                      type="button"
                      variant="ghost"
                    >
                      <TrashIcon className="size-4" />
                    </Button>
                  </div>
                );
              }

              return (
                <div
                  className={
                    index > 0
                      ? `${formSpacing.collectionRow} ${formSpacing.arrayItemSeparator}`
                      : formSpacing.collectionRow
                  }
                  data-testid={rowTestId}
                  key={item.key}
                >
                  <div className={KEY_REMOVE_GRID}>
                    {compactKeyField ? (
                      <AutoFormFieldRenderer
                        field={compactKeyField}
                        inheritedDisabled={isDisabled}
                        path={[...path, String(index), "key"]}
                      />
                    ) : null}
                    <Button
                      aria-label={removeItemLabel}
                      disabled={isDisabled}
                      onClick={removeEntry}
                      size="icon-sm"
                      testId={removeButtonTestId}
                      type="button"
                      variant="ghost"
                    >
                      <TrashIcon className="size-4" />
                    </Button>
                  </div>
                  {valueField ? (
                    <AutoFormFieldRenderer
                      field={compactValueField ?? valueField}
                      inheritedDisabled={isDisabled}
                      path={[...path, String(index), "value"]}
                    />
                  ) : null}
                </div>
              );
            })}
          </ArrayWrapperComponent>
        )}
      </ArrayController>
    </FieldWrapperComponent>
  );
}

"use client";

import { Text } from "@/components/ui/typography";
import { useAutoFormRenderContext, useAutoFormRuntimeContext } from "../context";
import type { ParsedField } from "../core-types";
import { useAutoFormEngine } from "../engine";
import { getPathInObject } from "../field-utils";
import { getFieldErrorMessage } from "../helpers";
import { getAutoFormFieldTestId } from "../test-ids";
import { AutoFormFieldRenderer } from ".";
import { getRenderedLabel, useFieldPresentation } from "./shared";

export function ObjectFieldRenderer({
  field,
  path,
  inheritedDisabled = false,
}: {
  field: ParsedField;
  path: string[];
  inheritedDisabled?: boolean;
}) {
  const { uiComponents } = useAutoFormRenderContext();
  const { errors } = useAutoFormEngine();
  const fullPath = path.join(".");
  const error = getFieldErrorMessage(errors, path);
  const label = getRenderedLabel(field);
  const { isVisible, renderField } = useFieldPresentation(field, path, inheritedDisabled);
  const { testIdPrefix } = useAutoFormRuntimeContext();

  // Check for errors on the object itself or any descendant field.
  // This ensures collapsible sections auto-expand when a child has an error.
  const errorAtPath = getPathInObject(errors as Record<string, unknown>, path);
  const hasDescendantError = errorAtPath !== undefined && errorAtPath !== null && typeof errorAtPath === "object";
  const hasError = Boolean(error) || hasDescendantError;

  if (!isVisible) {
    return null;
  }

  const ObjectWrapperComponent = uiComponents.ObjectWrapper;

  // Render the error inline as a sibling of the section only when present.
  // The previous version reserved a `min-h-5` slot unconditionally, which
  // added ~20px of whitespace under every nested object and drifted the
  // rhythm away from manually-composed Field-based forms. A naked
  // `<section>` + optional error line lets the parent's `formSpacing.form`
  // token drive the gap between siblings without any extra padding.
  return (
    <>
      <ObjectWrapperComponent field={renderField} hasError={hasError} label={label}>
        {(renderField.schema ?? []).map((subField) => (
          <AutoFormFieldRenderer
            field={subField}
            inheritedDisabled={Boolean(renderField.fieldConfig?.inputProps?.["disabled"])}
            key={`${path.join(".")}.${subField.key}`}
            path={[...path, subField.key]}
          />
        ))}
      </ObjectWrapperComponent>
      {error ? (
        <Text
          className="whitespace-pre-wrap text-destructive"
          data-testid={getAutoFormFieldTestId(testIdPrefix, fullPath, "error")}
          variant="small"
        >
          {error}
        </Text>
      ) : null}
    </>
  );
}

"use client";

import React from "react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useAutoFormRenderContext, useAutoFormRuntimeContext } from "../context";
import type { ParsedField } from "../core-types";
import { useAutoFormEngine } from "../engine";
import { getLabel, getPathInObject } from "../field-utils";
import { formSpacing } from "../form-spacing";
import { createEmptyFieldValue, getFieldErrorMessage, getFieldUiConfig } from "../helpers";
import { FormDepthProvider, useFormDepth } from "../layout-context";
import { getAutoFormFieldTestId } from "../test-ids";
import { AutoFormFieldRenderer } from ".";
import { getRenderedLabel, isDeprecatedField, isFieldHidden, useFieldPresentation } from "./shared";

export function OneofFieldRenderer({
  field,
  path,
  inheritedDisabled = false,
}: {
  field: ParsedField;
  path: string[];
  inheritedDisabled?: boolean;
}) {
  const { uiComponents } = useAutoFormRenderContext();
  const { deprecatedFields, evaluateRules } = useAutoFormRuntimeContext();
  const form = useAutoFormEngine();
  const fullPath = path.join(".");
  const oneofValue = (getPathInObject(form.values, path) as { case?: string; value?: unknown } | undefined) ?? {
    case: undefined,
    value: undefined,
  };
  const error = getFieldErrorMessage(form.errors, path);
  const label = getRenderedLabel(field);
  const { isDisabled, isVisible, renderField } = useFieldPresentation(field, path, inheritedDisabled);
  const FieldWrapperComponent = field.fieldConfig?.fieldWrapper ?? uiComponents.FieldWrapper;
  const { testIdPrefix } = useAutoFormRuntimeContext();
  const controlTestId = getAutoFormFieldTestId(testIdPrefix, fullPath, "control");
  const depth = useFormDepth();

  const ruleVisibleFields = (field.schema ?? []).filter((candidate) => {
    const candidateUi = getFieldUiConfig(candidate);
    const candidateValue = candidate.key === oneofValue.case ? oneofValue.value : undefined;
    return evaluateRules(candidateUi.visibleWhen, candidateValue);
  });
  const availableFields = ruleVisibleFields.filter((candidate) => !isFieldHidden(candidate, deprecatedFields));

  const selectedField = availableFields.find((candidate) => candidate.key === oneofValue.case);
  const selectedSchemaField = (field.schema ?? []).find((candidate) => candidate.key === oneofValue.case);
  const selectedDeprecatedDisabled =
    deprecatedFields === "disable" && selectedSchemaField !== undefined && isDeprecatedField(selectedSchemaField);
  const oneofDisabled = isDisabled || selectedDeprecatedDisabled;
  let selectedValueLabel: string | undefined;
  if (selectedField) {
    selectedValueLabel = getLabel(selectedField);
  } else if (oneofValue.case) {
    selectedValueLabel = "Unavailable selection";
  } else if (!field.required) {
    selectedValueLabel = "Not set";
  }

  let selectedFieldContent: React.ReactNode = null;
  if (selectedField) {
    if (selectedField.type === "object" && (!selectedField.schema || selectedField.schema.length === 0)) {
      selectedFieldContent = (
        <div className="rounded-lg border border-dashed bg-muted/30 px-4 py-3">
          <p className="text-muted-foreground text-sm">
            {getLabel(selectedField)} selected. No additional configuration needed.
          </p>
        </div>
      );
    } else {
      selectedFieldContent = (
        <FormDepthProvider depth={depth + 1}>
          <AutoFormFieldRenderer field={selectedField} inheritedDisabled={oneofDisabled} path={[...path, "value"]} />
        </FormDepthProvider>
      );
    }
  }

  React.useEffect(() => {
    if (!oneofValue.case) {
      return;
    }

    const stillVisibleByRule = ruleVisibleFields.some((candidate) => candidate.key === oneofValue.case);
    if (!stillVisibleByRule) {
      form.setValue(
        fullPath,
        { case: undefined, value: undefined },
        { shouldDirty: true, shouldTouch: true, shouldValidate: true }
      );
    }
  }, [form, fullPath, oneofValue.case, ruleVisibleFields]);

  if (!isVisible) {
    return null;
  }

  return (
    <FieldWrapperComponent error={error} field={renderField} id={fullPath} label={label}>
      <div className={formSpacing.oneofStack}>
        <Select
          items={[
            ...(field.required ? [] : [{ label: "Not set", value: null }]),
            ...availableFields.map((candidate) => ({
              label: getLabel(candidate),
              value: candidate.key,
            })),
          ]}
          onValueChange={(value) => {
            if (oneofDisabled) {
              return;
            }
            if (value === null) {
              form.setValue(
                fullPath,
                { case: undefined, value: undefined },
                { shouldDirty: true, shouldValidate: true }
              );
              return;
            }
            const nextField = availableFields.find((candidate) => candidate.key === value);
            form.clearErrors([`${fullPath}.value`]);
            form.setValue(
              fullPath,
              {
                case: value,
                value: oneofValue.case === value ? oneofValue.value : createEmptyFieldValue(nextField),
              },
              { shouldDirty: true, shouldTouch: true, shouldValidate: true }
            );
          }}
          value={oneofValue.case ?? null}
        >
          <SelectTrigger aria-label={label} disabled={oneofDisabled} id={fullPath} testId={controlTestId}>
            <SelectValue placeholder="Choose a field">{selectedValueLabel}</SelectValue>
          </SelectTrigger>
          <SelectContent>
            {field.required ? null : (
              <SelectItem testId={getAutoFormFieldTestId(testIdPrefix, fullPath, "option-not-set")} value={null}>
                Not set
              </SelectItem>
            )}
            {availableFields.map((candidate) => (
              <SelectItem
                disabled={deprecatedFields === "disable" && isDeprecatedField(candidate)}
                key={candidate.key}
                testId={getAutoFormFieldTestId(testIdPrefix, fullPath, `option-${candidate.key}`)}
                value={candidate.key}
              >
                {getLabel(candidate)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {selectedFieldContent}
      </div>
    </FieldWrapperComponent>
  );
}

import React from "react";

import { useAutoFormRuntimeContext } from "../context";
import type { ParsedField } from "../core-types";
import { getFieldHints } from "../core-types";
import { getLabel, getPathInObject } from "../field-utils";
import { getFieldUiConfig, resolveRenderFieldType } from "../helpers";
import type { DeprecatedFieldPolicy } from "../types";

export function isDeprecatedField(field: ParsedField): boolean {
  return getFieldHints(field)?.deprecated === true;
}

export function isFieldHidden(field: ParsedField, policy: DeprecatedFieldPolicy): boolean {
  const customData = (field.fieldConfig?.customData ?? {}) as Record<string, unknown>;
  return Boolean(customData["hidden"]) || (policy === "hide" && isDeprecatedField(field));
}

export function cloneFieldWithDisabled(field: ParsedField, disabled: boolean): ParsedField {
  if (!disabled) {
    return field;
  }

  return {
    ...field,
    fieldConfig: {
      ...(field.fieldConfig ?? {}),
      inputProps: {
        ...(field.fieldConfig?.inputProps ?? {}),
        disabled: true,
      },
    },
  };
}

export function useFieldPresentation(field: ParsedField, path: string[], inheritedDisabled = false) {
  const { deprecatedFields, formValues, evaluateRules } = useAutoFormRuntimeContext();
  const fieldValue = getPathInObject(formValues, path);
  const uiConfig = getFieldUiConfig(field);
  const customData = (field.fieldConfig?.customData ?? {}) as Record<string, unknown>;
  const isHidden = isFieldHidden(field, deprecatedFields);
  const isImmutable = Boolean(customData["immutable"]);
  const isVisible = !isHidden && evaluateRules(uiConfig.visibleWhen, fieldValue);
  const isDisabledByRule =
    uiConfig.disabledWhen && uiConfig.disabledWhen.length > 0
      ? evaluateRules(uiConfig.disabledWhen, fieldValue)
      : false;
  const isDisabled =
    inheritedDisabled ||
    isDisabledByRule ||
    isImmutable ||
    (deprecatedFields === "disable" && isDeprecatedField(field));
  const renderField = React.useMemo(() => cloneFieldWithDisabled(field, isDisabled), [field, isDisabled]);

  return {
    fieldValue,
    isDisabled,
    isVisible,
    renderField,
    renderType: resolveRenderFieldType(field),
  };
}

export function cloneFieldForCompactRow(field: ParsedField): ParsedField {
  const label = getLabel(field);

  const existingCustomData = (field.fieldConfig?.customData ?? {}) as Record<string, unknown>;
  const existingUi = (existingCustomData["ui"] ?? {}) as Record<string, unknown>;

  return {
    ...field,
    fieldConfig: {
      ...(field.fieldConfig ?? {}),
      customData: {
        ...existingCustomData,
        compactRow: true,
        ui: {
          ...existingUi,
          example: "",
          help: "",
        },
      },
      description: "",
      inputProps: {
        ...(field.fieldConfig?.inputProps ?? {}),
        placeholder:
          (field.fieldConfig?.inputProps?.["placeholder"] as string | undefined) ||
          (field.type === "select" || field.type === "boolean" ? undefined : label),
      },
      label: "",
    },
  };
}

export function getRenderedLabel(field: ParsedField): string {
  if (typeof field.fieldConfig?.label === "string") {
    return field.fieldConfig.label;
  }

  return getLabel(field);
}

export function isComplexCollectionField(field: ParsedField | undefined): boolean {
  if (!field) {
    return false;
  }

  const renderType = resolveRenderFieldType(field);
  return ["object", "array", "map", "oneof", "json"].includes(renderType);
}

