                    <span
                      className={isComplete ? "min-h-5 w-px flex-1 bg-primary" : "min-h-5 w-px flex-1 bg-border"}
                      data-orientation="vertical"
                      data-testid="step-connector"
                    />
                  ) : null}
                </span>
                <span
                  aria-hidden="true"
                  className={
                    isCurrent
                      ? "min-w-0 pt-1 pb-5 font-semibold text-sm"
